/// <summary>
///     The <c>NDX_KBVEmailSend</c> is the exetension class for table <c>common</c>
/// </summary>
public class NDX_KBVEmailSend extends common
{
}

Method.Source:
/// <summary>
///    AVA <c>createProt</c> method.
/// </summary>
/// <param name="_email">
///    <c>Email</c> as type
/// </param>
/// <param name="_ndx_KBVMail">
///    <c>NDX_KBVMail</c> as type
/// </param>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_hcmWorkerRecId">
///    <c>HCMWorkerRecId</c> as type
/// </param>
/// <param name="_kcs_KBVInfoArea">
///    <c>KCS_KBVInfoArea</c> as type
/// </param>
public void createProt( Email                       _email,
                        NDX_KBVMail                 _ndx_KBVMail,
                        KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID,
                        HCMWorkerRecId              _hcmWorkerRecId,
                        KCS_KBVInfoArea             _kcs_KBVInfoArea = KCS_KBVInfoArea::BVChanged)
{
    ttsbegin;
    this.selectForUpdate(true);

    this.Email                      = _email;
    this.NDX_KBVMail                = _ndx_KBVMail;
    this.KCS_KBVBuildingProjectID   = _kcs_KBVBuildingProjectID;
    if(_ndx_KBVMail == NDX_KBVMail::KBV_Info)
    {
        this.KCS_KBVInfoArea  = _kcs_KBVInfoArea;
    }
    this.AVAWorker                  = _hcmWorkerRecId;

    this.insert();
    ttscommit;
}

/// <summary>
///    AVA <c>findLast</c> method.
/// </summary>
/// <param name="_emailType">
///    <c>NDX_KBVMail</c> as type
/// </param>
/// <returns>
///    <c>NDX_KBVEmailSend</c> as return value
/// </returns>
static NDX_KBVEmailSend findLast(NDX_KBVMail _emailType =  NDX_KBVMail::KBV_Info)
{
    NDX_KBVEmailSend    nDX_KBVEmailSend;

    select firstOnly nDX_KBVEmailSend
    order by recId desc
    where nDX_KBVEmailSend.NDX_KBVMail == _emailType;

    return nDX_KBVEmailSend;
}

/// <summary>
///    AVA <c>setWorker</c> method.
/// </summary>
void setWorker()
{
    HcmWorker                   locHcmWorker;
    DirPerson                   locDirPerson;
    DirPartyTable               locDirPartyTable;
    LogisticsElectronicAddress  locLogisticsElectronicAddress;

    select firstonly locHcmWorker
        join    locDirPerson
        where   locDirPerson.RecId == locHcmWorker.Person
            join    locDirPartyTable
            where   locDirPartyTable.RecId == locDirPerson.RecId
                join    locLogisticsElectronicAddress
                where   locDirPartyTable.PrimaryContactEmail    == locLogisticsElectronicAddress.RecId
                    &&  locLogisticsElectronicAddress.Locator   ==  this.Email;

    if(locHcmWorker.RecId)
    {
        this.AVAWorker = locHcmWorker.RecId;
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>int</returns>
static int setWorkerIfEmpty()
{
    NDX_KBVEmailSend    nDX_KBVEmailSend;
    NDX_KBVEmailSend    nDX_KBVEmailSendGrp;
    int                 nAnz;

    while select crosscompany dataAreaId from nDX_KBVEmailSendGrp
    group by dataAreaId
    {
        changecompany(nDX_KBVEmailSendGrp.dataAreaId)
        {
            nDX_KBVEmailSend = null;

            ttsbegin;

            while select forUpdate nDX_KBVEmailSend
            where   !nDX_KBVEmailSend.AVAWorker
            {
                nDX_KBVEmailSend.setWorker();
                nDX_KBVEmailSend.update();
                ++nAnz;
            }
            ttscommit;
        }
    }
    return nAnz;
}
